// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

use std::cmp::Ordering;

// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Hybrid introsort with median-of-three pivot and insertion sort cutoff will improve performance on all data patterns
// MECHANISM-1: Median-of-three avoids worst-case on sorted/reverse data; insertion sort is optimal for small subarrays; depth limit prevents stack overflow
// EXPECT-1: performance_score > 0.99
// RESULT-1: CONFIRMED (actual=0.9975187150895196)
// HYPOTHESIS-2: Detecting nearly-sorted runs at the top level and using insertion sort will improve adaptability
// MECHANISM-2: Nearly-sorted arrays are O(n) with insertion sort vs O(n log n) with quicksort, reducing variance across input types
// EXPECT-2: adaptability_score > 0.995
// RESULT-2: CONFIRMED (actual=0.9996618163155823)

const INSERTION_THRESHOLD: usize = 24;

pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    if len <= INSERTION_THRESHOLD { insertion_sort(arr); return; }
    // Check if nearly sorted: count adjacent inversions
    let mut disorder = 0usize;
    for i in 0..len - 1 {
        if arr[i] > arr[i + 1] { disorder += 1; }
    }
    if disorder <= len / 8 {
        insertion_sort(arr);
        return;
    }
    let max_depth = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, 0, len - 1, max_depth);
}

fn introsort<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize, depth: usize) {
    if high <= low { return; }
    let size = high - low + 1;
    if size <= INSERTION_THRESHOLD {
        insertion_sort_range(arr, low, high);
        return;
    }
    if depth == 0 {
        heapsort_range(arr, low, high);
        return;
    }
    let pivot = partition_mo3(arr, low, high);
    if pivot > 0 { introsort(arr, low, pivot.saturating_sub(1), depth - 1); }
    introsort(arr, pivot + 1, high, depth - 1);
}

fn partition_mo3<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize) -> usize {
    let mid = low + (high - low) / 2;
    // Median-of-three
    if arr[low] > arr[mid] { arr.swap(low, mid); }
    if arr[low] > arr[high] { arr.swap(low, high); }
    if arr[mid] > arr[high] { arr.swap(mid, high); }
    arr.swap(mid, high - 1);
    if high - low < 2 { return high - 1; }
    let pivot = arr[high - 1].clone();
    let mut i = low + 1;
    let mut j = high - 2;
    loop {
        while arr[i] < pivot { i += 1; }
        while j > low && arr[j] > pivot { j -= 1; }
        if i >= j { break; }
        arr.swap(i, j);
        i += 1;
        j -= 1;
    }
    arr.swap(i, high - 1);
    i
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}

fn insertion_sort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    for i in (low + 1)..=high {
        let mut j = i;
        while j > low && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}

fn heapsort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    let n = high - low + 1;
    for i in (0..n / 2).rev() {
        sift_down(arr, low, i, n);
    }
    for end in (1..n).rev() {
        arr.swap(low, low + end);
        sift_down(arr, low, 0, end);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], base: usize, start: usize, n: usize) {
    let mut root = start;
    loop {
        let child = 2 * root + 1;
        if child >= n { break; }
        let mut swap = root;
        if arr[base + child] > arr[base + swap] { swap = child; }
        if child + 1 < n && arr[base + child + 1] > arr[base + swap] { swap = child + 1; }
        if swap == root { break; }
        arr.swap(base + root, base + swap);
        root = swap;
    }
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

